export type Dir =
  | Initial
  | Final
  | Unresolved
  | Word
  | None;

export const Dir = Object.freeze({
  Initial: Object.freeze({ kind: "Initial" } as Initial),
  Final: Object.freeze({ kind: "Final" } as Final),
  Unresolved: Object.freeze({ kind: "Unresolved" } as Unresolved),
  Word: Object.freeze({ kind: "Word" } as Word),
  None: Object.freeze({ kind: "None" } as None)
});

export function compareDir(a: Dir, b: Dir): number {
  if (a === b) return 0;
  if (a.kind === "Initial") return 0 - (b.kind === "Initial" ? 0 : 0);
  if (a.kind === "Final") return 1 - (b.kind === "Final" ? 1 : 0);
  if (a.kind === "Unresolved") return 2 - (b.kind === "Unresolved" ? 2 : 0);
  if (a.kind === "Word") return 3 - (b.kind === "Word" ? 3 : 0);
  if (a.kind === "None") return 4 - (b.kind === "None" ? 4 : 0);
  return 0;
}
